static void gsta_gpio_setup ( struct gsta_gpio * chip ) { struct gpio_chip * gpio = & chip -> gpio ; static int gpio_base ; gpio -> label = dev_name ( chip -> dev ) ; gpio -> owner = THIS_MODULE ; gpio -> direction_input = gsta_gpio_direction_input ; gpio -> get = gsta_gpio_get ; gpio -> direction_output = gsta_gpio_direction_output ; gpio -> set = gsta_gpio_set ; gpio -> base = gpio_base ; gpio -> ngpio = GSTA_NR_GPIO ; gpio -> can_sleep = false ; gpio -> to_irq = gsta_gpio_to_irq ; if ( ! gpio_base ) { gpio_base = - 1 ; } } 